class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist,
   *the input card info and withdraw status
   *and number should be cleared*/
  ejectCard(): boolean {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.CardID === this.InputCard.CardID,
              description: "o.CardID=InputCard.CardID",
            })
              .and({
                logic: () => o.Password === this.PasswordValidated,
                description: "o.Password=PasswordValidated",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(o|o.CardID=InputCard.CardIDando.Password=PasswordValidated)",
    }).build().pass;
    let IsDeposit: boolean = l({
      logic: () => true,
      description: "true",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(inputCard),
        description: "inputCard.oclIsUndefined()",
      })
        .and({
          logic: () => this.CardIDValidated === true,
          description: "CardIDValidated=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let inputCard: BankCard;
    return l({
      execute: () => (inputCard = new BankCard()),
      description: "inputCard.oclIsNew()",
    })
      .and({
        execute: () =>
          l().if({
            logic: () =>
              l({
                logic: () => (inputCard = new BankCard()),
                description: "inputCard.oclIsNew()",
              }),
            description: "inputCard.oclIsNew()",
            then: l({
              execute: () => false,
              description: "result=false",
            }),
            else: l({
              execute: () =>
                (inputCard.Balance = inputCard.Balance - this.DepositedNumber),
              description:
                "inputCard.Balance=inputCard.Balance-DepositedNumber",
            }).and({
              execute: () => true,
              description: "result=true",
            }),
          }),
        description:
          "(ifinputCard.oclIsNew()thenresult=falseelseinputCard.Balance=inputCard.Balance-DepositedNumberandresult=trueendif)",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

